rows=[]
for index,t in enumerate(topics):
    linked=[l for l in abx if t['key'] in l.get('topic_ids',[])]
    if index in scope:
        group,kind,gap=scope[index]; relevance='Treatment/prophylaxis/stewardship review'; status='Partial linked lessons' if linked else 'No linked antibiotic lesson'
    elif index in cross:
        group=t['section'];kind='Cross-link / safety / differential';gap=cross[index];relevance='Context only';status='Conditional cross-link required'
    elif index in other:
        group=t['section'];kind='Other anti-infective';gap=other[index];relevance='Separate anti-infective scope';status='Outside antibacterial count'
    else:
        group=t['section'];kind='No direct antibiotic teaching identified';gap='No direct antibacterial treatment/prophylaxis pathway identified in this entry’s stated scope. This is not a claim that infection can never coexist, nor clinical validation of the rest of the topic.';relevance='No direct scope identified';status='Not a direct antibiotic gap'
    rows.append(dict(index=index,topic_id=t['key'],title=t['section'],group=group,kind=kind,relevance=relevance,status=status,linked_lesson_ids=[l['id'] for l in linked],gap=gap,stored_review=t['review'],stored_evidence=[dict(id=r['id'],url=r['url'],locator=r['locator']) for r in t.get('evidence_records',[])],legacy_source_url=t.get('url'),complete_verified=False))

extras=[]
for l in lessons:
    if l['track']!='condition':continue
    label,gap=supplemental.get(l['id'],('No direct antibacterial scope identified','No direct antibacterial regimen indicated by the currently loaded facts; fungal therapy and other medication gaps are outside this audit’s antibacterial count.'))
    extras.append(dict(topic_id=l['id'],title=l['title'],classification=label,gap=gap,stored_lesson_gaps=l['gaps'],linked_antibiotic_lessons=[a['id'] for a in abx if l['id'] in a.get('topic_ids',[])],source_ids=l['source_ids'],complete_verified=False))

regimens=[]
for l in abx:
    required=['indication','population','drug','dose','route','frequency','duration','adjustment','maximum']
    ps=[safety[n] for n in l.get('medication_names',[]) if n in safety]
    regimens.append(dict(id=l['id'],title=l['title'],topic_ids=l.get('topic_ids',[]),medication_names=l.get('medication_names',[]),regimen_fields_present=all(l['regimen'].get(k) for k in required),all_named_drugs_have_profile=all(n in safety for n in l.get('medication_names',[])),all_source_ids_resolve=all(s in sources for s in l['source_ids']),source_ids=l['source_ids'],source_urls=[sources[s]['url'] for s in l['source_ids']],gaps=l['gaps'],renal_evidence=[dict(drug=p['drug'],**p['renal']) for p in ps],hepatic_evidence=[dict(drug=p['drug'],**p['hepatic']) for p in ps],audit_status='Scoped stored lesson; not independently revalidated or complete condition coverage'))

names=sorted({n for l in abx for n in l.get('medication_names',[])})
stats=dict(original_topics=len(rows),supplemental_conditions=len(extras),original_topics_with_linked_antibiotic_regimens=sum(bool(r['linked_lesson_ids']) for r in rows),original_entries_flagged_for_treatment_prophylaxis_stewardship_review=len(scope),flagged_original_entries_without_linked_lessons=sum(not rows[i]['linked_lesson_ids'] for i in scope),antibiotic_tagged_regimen_lessons=len(abx),named_drugs_in_tagged_lessons=len(names),supplemental_conditions_with_linked_antibiotic_regimens=sum(bool(r['linked_antibiotic_lessons']) for r in extras),conditions_demonstrated_complete=0)
assert stats['original_topics']==156 and stats['supplemental_conditions']==12
